ThetoLocaleString()method is available for many JavaScript datatypes / objects:

You canspecify a languageand country code to format a value for a specific locale.

With options,toLocaleString()can format numbers as currency.

Thestyle:"percent"option formats a number as a percentage.

You can control the number of decimal digits withminimumFractionDigitsandmaximumFractionDigits.

Dates can also be formatted withtoLocaleString().

Many options can be used to control how dates are displayed.

A clever use oftoLocaleString()is to make file sizes easier to read.

For arrays, thetoLocaleString()methods converts each array element.

### Code Snippets

```
let num = 1234567.89;
let text = num.toLocaleString();

---

let num = 1234567.89;
let us = num.toLocaleString("en-US");
let de = num.toLocaleString("de-DE");
let no = num.toLocaleString("no-NO");

---

let price = 1299.95;
let dollars = price.toLocaleString("en-US",
{style:"currency", currency:"USD"});
let euros = price.toLocaleString("de-DE",
{style:"currency", currency:"EUR"});
let kroner = price.toLocaleString("no-NO",
{style:"currency", currency:"NOK"});

---

let score = 0.875;
let result = score.toLocaleString("en-US", {style:"percent"});

---

let num = 3.14159;
let text = num.toLocaleString("en-US", {
minimumFractionDigits: 2,
maximumFractionDigits: 2
});

---

let date = new Date();
let text = date.toLocaleString("en-US");

---

let date = new Date();
let text = date.toLocaleString("en-US", {
weekday: "long",
year: "numeric",
month: "long",
day: "numeric"
});

---

function fileSize(bytes) {
if (bytes < 1024) return bytes + " bytes";
if (bytes < 1024 * 1024) return (bytes / 1024).toLocaleString("en-US", {maximumFractionDigits: 1}) + " KB";
return (bytes / 1024 / 1024).toLocaleString("en-US", {maximumFractionDigits: 1}) + " MB";
}
let size = 1536000;
let text = fileSize(size);

---

const dates = [
new Date("2026-01-01"),
new Date("2026-12-24")
];
let text = dates.toLocaleString("en-US");
```
